 "content": "def transform(grid):
    """Copy the rightward extension of the lower repeated motif into the upper one."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Find separated bands containing any non-background motif cells.
    active = [any(value != background for value in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return out

    (top0, top1), (bottom0, bottom1) = bands[:2]
    top_rows = grid[top0:top1]
    bottom_rows = grid[bottom0:bottom1]
    top_right = max((c for row in top_rows for c, v in enumerate(row) if v != background), default=-1)
    bottom_right = max((c for row in bottom_rows for c, v in enumerate(row) if v != background), default=-1)
    if bottom_right <= top_right:
        return out

    # The lower copy has a longer right-hand tail. Mark only the cells of
    # that continuation in corresponding rows, leaving other motif differences intact.
    height = min(top1 - top0, bottom1 - bottom0)
    for dr in range(height):
        for c in range(top_right + 1, min(bottom_right, w - 1) + 1):
            if grid[bottom0 + dr][c] != background and grid[top0 + dr][c] == background:
                out[top0 + dr][c] = 1
    return out
